<?php
require_once __DIR__.'/includes/session_bootstrap.php';startVfnWebSession();require_once __DIR__.'/execute/config.php';require_once __DIR__.'/includes/language.php';require_once __DIR__.'/includes/web_session.php';
function h($value):string{return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
$pdo=new PDO("mysql:host=$dbHost;dbname=$dbName;charset=utf8mb4",$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
if(empty($_SESSION['web_user_id'])||!validateVfnWebSession($pdo)){header('Location:index.php?type=error&message=login_required');exit;}
$id=max(0,(int)($_GET['id']??0));$stmt=$pdo->prepare("SELECT f.*,u.username,u.real_name FROM pilot_flights f INNER JOIN users u ON u.id=f.user_id WHERE f.id=:id LIMIT 1");$stmt->execute(['id'=>$id]);$flight=$stmt->fetch(PDO::FETCH_ASSOC);if(!$flight){http_response_code(404);}
$points=[];if($flight){$track=$pdo->prepare("SELECT latitude,longitude,altitude,heading,created_at FROM pilot_tracks WHERE session_token=:token AND callsign=:callsign ORDER BY id");$track->execute(['token'=>$flight['session_token'],'callsign'=>$flight['callsign']]);$all=$track->fetchAll(PDO::FETCH_ASSOC);$step=max(1,(int)ceil(count($all)/2500));foreach($all as $index=>$point){if($index%$step===0||$index===count($all)-1)$points[]=[(float)$point['latitude'],(float)$point['longitude'],(float)$point['altitude'],(string)$point['created_at']];}}
?>
<!doctype html><html lang="<?php echo h($currentLanguage);?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo h(t('flight_details_title'));?></title><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>body{margin:0;background:#07141f;color:#d7e8ff;font-family:Arial}.shell{width:min(1300px,calc(100% - 36px));margin:28px auto}.card{background:#0d1d2a;border:1px solid #285475;border-radius:8px;padding:18px;margin-bottom:16px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{background:#081925;padding:14px;border-radius:6px}.stat span{display:block;color:#8ba7bf;font-size:12px}.stat strong{color:#55e9c1;font-size:18px}#flightMap{height:540px;border-radius:7px}.route{font-size:25px;color:#7fc8ff}a{color:#65bdff}@media(max-width:800px){.stats{grid-template-columns:1fr 1fr}#flightMap{height:400px}}</style></head><body><?php require __DIR__.'/includes/header.php';?><main class="shell"><?php if(!$flight):?><section class="card"><h1><?php echo h(t('flight_not_found'));?></h1></section><?php else:?><section class="card"><h1><?php echo h($flight['callsign']);?> · <?php echo h($flight['aircraft_icao']);?></h1><p><a href="profile.php?id=<?php echo (int)$flight['user_id'];?>"><?php echo h($flight['real_name']?:$flight['username']);?></a></p><div class="route"><?php echo h($flight['departure_airport']?:'ZZZZ');?> → <?php echo h($flight['arrival_airport']?:'ZZZZ');?></div></section><section class="stats"><div class="stat"><span><?php echo h(t('profile_flight_date'));?></span><strong><?php echo h(date('d.m.Y H:i',strtotime($flight['started_at'])));?></strong></div><div class="stat"><span><?php echo h(t('profile_flight_duration'));?></span><strong><?php echo sprintf('%d:%02d h',floor($flight['duration_seconds']/3600),floor(($flight['duration_seconds']%3600)/60));?></strong></div><div class="stat"><span><?php echo h(t('profile_flight_distance'));?></span><strong><?php echo h(number_format((float)$flight['distance_nm'],1,',','.'));?> NM</strong></div><div class="stat"><span><?php echo h(t('profile_flight_landing_rate'));?></span><strong><?php echo $flight['landing_rate_fpm']!==null?h($flight['landing_rate_fpm']).' fpm':'—';?></strong></div></section><section class="card"><h2><?php echo h(t('flight_route_map'));?></h2><?php if(!$points):?><p><?php echo h(t('flight_route_unavailable'));?></p><?php else:?><div id="flightMap"></div><?php endif;?></section><?php endif;?></main><?php require __DIR__.'/includes/footer.php';?><?php if($points):?><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const points=<?php echo json_encode($points);?>;const map=L.map('flightMap');L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);const line=L.polyline(points.map(p=>[p[0],p[1]]),{color:'#168cff',weight:4}).addTo(map);L.circleMarker([points[0][0],points[0][1]],{color:'#4cff9b',radius:7}).addTo(map);L.circleMarker([points.at(-1)[0],points.at(-1)[1]],{color:'#ff6464',radius:7}).addTo(map);map.fitBounds(line.getBounds(),{padding:[25,25]});</script><?php endif;?></body></html>
